// Words made of parts: [the English's shape, its words in the language (m: the match, t: tr in that language)]. Tried in order.
const LIST_JA = { "in the list": "一覧", automatic: "自動", quick: "クイック" }, LIST_ZH = { "in the list": "列表", automatic: "自动", quick: "快速" };
const kinds = (s, names, sep) => s.split(", ").map((p) => { const m = /^(\d+) (.+)$/.exec(p); return m ? `${names[m[2]] || m[2]} ${m[1]}` : p; }).join(sep);
export const PATTERNS_JA = [
  [/^An unofficial fan rebuild of the Tsukihime remake\. Choose a page above: (.+), or (.+) to start the game\.$/,
    (m, t) => `月姫リメイクの非公式なファンによる再構築版です。上のページを選んでください：${m[1].split(", ").map((n) => `「${t(n)}」`).join("")}、ゲームを始めるなら「${t(m[2])}」。`],
  [/^Saved as (.+)\.$/, (m) => `${m[1]} として保存しました。`],
  [/^Loaded (.+)\.$/, (m, t) => `${t(m[1])} を読み込みました。`],
  [/^This version: (.+)$/, (m) => `このバージョン：${m[1]}`],
  [/^An update is available \((.+)\)\.$/, (m) => `アップデートがあります（${m[1]}）。`],
  [/^An update is available \((.+)\)\.\nDownload it now\?$/, (m) => `アップデートがあります（${m[1]}）。\n今すぐダウンロードしますか？`],
  [/^Downloading the update {2}(\d+)%\nPress to stop$/, (m) => `アップデートをダウンロード中  ${m[1]}%\n押すと中止します`],
  [/^(.+) needs a download \((.+)\),\nwith the latest update\.\nDownload it now\?$/, (m) => `${m[1]}のダウンロードが必要です（${m[2]}）。\n最新のアップデートも含みます。\n今すぐダウンロードしますか？`],
  [/^(.+) needs a download \((.+)\)\.\nDownload it now\?$/, (m) => `${m[1]}のダウンロードが必要です（${m[2]}）。\n今すぐダウンロードしますか？`],
  [/^Downloading (.+) {2}(\d+)%\nPress to stop$/, (m) => `${m[1]}をダウンロード中  ${m[2]}%\n押すと中止します`],
  [/^(.+) needs a download\.\nNo connection to arcueid\.date\.$/, (m) => `${m[1]}のダウンロードが必要です。\narcueid.date に接続できません。`],
  [/^(.+) could not be downloaded\. Nothing was changed\.$/, (m) => `${m[1]}をダウンロードできませんでした。何も変更されていません。`],
  [/^(.+) was stopped\. Nothing was changed\.$/, (m) => `${m[1]}のダウンロードを中止しました。何も変更されていません。`],
  [/^saves made here: (.+)$/, (m) => `ここで作ったセーブ：${kinds(m[1], LIST_JA, "、")}`],
  [/^(.+) is loaded: these are its own\. Your own are put aside until it is removed\.$/,
    (m, t) => `${t(m[1])}を読み込んでいます。表示しているのはその内容です。あなた自身のものは、取り外すまで脇に置かれています。`],
];
export const PATTERNS_ZH = [
  [/^An unofficial fan rebuild of the Tsukihime remake\. Choose a page above: (.+), or (.+) to start the game\.$/,
    (m, t) => `月姬重制版的非官方粉丝重建版。请选择上方的页面：${m[1].split(", ").map((n) => `“${t(n)}”`).join("、")}，或选择“${t(m[2])}”开始游戏。`],
  [/^Saved as (.+)\.$/, (m) => `已保存为 ${m[1]}。`],
  [/^Loaded (.+)\.$/, (m, t) => `已载入 ${t(m[1])}。`],
  [/^This version: (.+)$/, (m) => `当前版本：${m[1]}`],
  [/^An update is available \((.+)\)\.$/, (m) => `有可用的更新（${m[1]}）。`],
  [/^An update is available \((.+)\)\.\nDownload it now\?$/, (m) => `有可用的更新（${m[1]}）。\n现在下载吗？`],
  [/^Downloading the update {2}(\d+)%\nPress to stop$/, (m) => `正在下载更新  ${m[1]}%\n按下即可停止`],
  [/^(.+) needs a download \((.+)\),\nwith the latest update\.\nDownload it now\?$/, (m) => `${m[1]}需要下载（${m[2]}），\n并附带最新的更新。\n现在下载吗？`],
  [/^(.+) needs a download \((.+)\)\.\nDownload it now\?$/, (m) => `${m[1]}需要下载（${m[2]}）。\n现在下载吗？`],
  [/^Downloading (.+) {2}(\d+)%\nPress to stop$/, (m) => `正在下载${m[1]}  ${m[2]}%\n按下即可停止`],
  [/^(.+) needs a download\.\nNo connection to arcueid\.date\.$/, (m) => `${m[1]}需要下载。\n无法连接到 arcueid.date。`],
  [/^(.+) could not be downloaded\. Nothing was changed\.$/, (m) => `无法下载${m[1]}。没有任何改动。`],
  [/^(.+) was stopped\. Nothing was changed\.$/, (m) => `${m[1]}的下载已停止。没有任何改动。`],
  [/^saves made here: (.+)$/, (m) => `在这里做的存档：${kinds(m[1], LIST_ZH, "，")}`],
  [/^(.+) is loaded: these are its own\. Your own are put aside until it is removed\.$/,
    (m, t) => `已载入${t(m[1])}：显示的是它的内容。你自己的会被暂存，直到移除它。`],
];
